actions.script:
canView = false; canCreate = false; canUpdate = false; canDelete = false; archived = false; repository = null; projectList = []
// a client contact (PROJECT_CLIENT; impl-projects.md P10b): views a repository its project shares (check#GitRepositoryAuthz)
// and nothing more, whatever its groups: no rights to change, no storage, mirror or administration fields, no SSH
isClient = ec.user.hasPermission('PROJECT_CLIENT')
isAdmin = !isClient && ec.user.isInGroup('ADMIN')
if (!repositoryId) return
ec.message.pushErrors()
try {
    const access = ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess').parameters({repositoryId}).call() || {}
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    const row = ec.entity.find('moqui.resource.GitRepository').condition('repositoryId', repositoryId).disableAuthz().one()
    if (row == null || !access.canView) return
    canView = true; canCreate = !!access.canCreate; canUpdate = !!access.canUpdate; canDelete = !!access.canDelete; archived = !!access.archived
    const L = (text) => ec.l10n.localize(text)
    repository = {repositoryId: row.repositoryId, description: row.description || '', repositoryKind: row.repositoryKind || 'local',
        branch: row.branch || 'main', headCommitId: row.headCommitId || null, lastUpdateDate: row.lastUpdateDate || null,
        archivedDate: row.archivedDate || null, defaultMergeMethodEnumId: row.defaultMergeMethodEnumId || 'GmmMerge',
        remoteUrl: row.repositoryKind === 'remote' ? (row.remoteUrl || '') : '', fetchIntervalMinutes: row.fetchIntervalMinutes ?? null,
        lastFetchDate: row.lastFetchDate || null, lastFetchError: row.lastFetchError || null, objectCount: row.objectCount ?? null,
        storedBytes: row.storedBytes ?? null, lastGcDate: row.lastGcDate || null, lastGcResult: row.lastGcResult || null,
        kindLabel: row.repositoryKind === 'db' ? L('In the database') : row.repositoryKind === 'remote' ? L('Mirror') : L('On disk')}
    const linked = ec.service.sync().name('mantle.work.GitServices.get#RepositoryProjects').parameters({repositoryId}).call() || {}
    const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
    const visible = Array.from(vis.visibleProjectIds || [])
    for (const link of Array.from(linked.linkList || [])) {
        if (!vis.allProjects && !visible.includes(link.workEffortId)) continue
        const project = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', link.workEffortId).one()
        projectList.push({workEffortId: link.workEffortId, workEffortName: project?.workEffortName || link.workEffortId, fromDate: link.fromDate})
    }
    const urls = ec.service.sync().name('org.moqui.git.GitServices.get#GitCloneUrls').parameters({repositoryId}).call() || {}
    httpsUrl = urls.httpsUrl || null
    sshUrl = urls.sshUrl || null
    if (isClient) {
        canCreate = false; canUpdate = false; canDelete = false; sshUrl = null
        repository = {repositoryId: repository.repositoryId, description: repository.description, repositoryKind: repository.repositoryKind,
            branch: repository.branch, headCommitId: repository.headCommitId, lastUpdateDate: repository.lastUpdateDate,
            archivedDate: repository.archivedDate, kindLabel: repository.kindLabel}
    }
} catch (err) {
    ec.logger.warn(`Repository ${repositoryId}: its access was not read: ${err && err.message ? err.message : err}`)
    canView = false
} finally { ec.message.clearErrors(); ec.message.popErrors() }

rowList = []; rowCount = 0; counts = {mine: 0, all: 0, mirrors: 0, archived: 0}
// a client contact (impl-projects.md P10b): the repositories its projects share (find#GitRepositories, the view right), no SSH
const isClient = ec.user.hasPermission('PROJECT_CLIENT')
if (!['mine', 'all', 'mirrors', 'archived'].includes(list)) list = 'mine'
const L = (text) => ec.l10n.localize(text)
const found = Array.from(ec.service.sync().name('org.moqui.git.GitServices.find#GitRepositories').parameters({text: text || null,
    includeArchived: true, pageNoLimit: true}).call()?.repositoryList || [])
if (ec.message.hasError()) return
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
const mine = new Set(Array.from(vis.memberProjectIds || []))
const visible = new Set(Array.from(vis.visibleProjectIds || []))
const ids = found.map((repo) => repo.repositoryId)
const links = ids.length ? Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitRepository').condition('repositoryId', 'in', ids)
        .conditionDate('fromDate', 'thruDate', null).list()) : []
const projectNames = {}
const projectIds = Array.from(new Set(links.map((link) => link.workEffortId)))
if (projectIds.length) for (const project of Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', projectIds)
        .selectField('workEffortId,workEffortName').list())) projectNames[project.workEffortId] = project.workEffortName || project.workEffortId
const rows = found.map((repo) => {
    const projects = links.filter((link) => link.repositoryId === repo.repositoryId).map((link) => link.workEffortId)
    return Object.assign({}, repo, {archived: !!repo.archivedDate, isMine: projects.some((id) => mine.has(id)),
        projectList: projects.filter((id) => vis.allProjects || visible.has(id)).map((id) => ({workEffortId: id, workEffortName: projectNames[id] || id}))})
})
const inList = (row, key) => key === 'archived' ? row.archived : row.archived ? false : key === 'mine' ? row.isMine
    : key === 'mirrors' ? row.repositoryKind === 'remote' : true
for (const key of Object.keys(counts)) counts[key] = rows.filter((row) => inList(row, key)).length
const chosen = rows.filter((row) => inList(row, list))
rowCount = chosen.length
const size = Math.max(1, Number(pageSize) || 25)
for (const row of chosen.slice(Number(pageIndex || 0) * size, (Number(pageIndex || 0) + 1) * size)) {
    let urls = {}
    ec.message.pushErrors()
    try { urls = ec.service.sync().name('org.moqui.git.GitServices.get#GitCloneUrls').parameters({repositoryId: row.repositoryId}).call() || {} }
    catch (err) { ec.logger.warn(`Repositories: no clone URLs of ${row.repositoryId}: ${err}`) }
    finally { ec.message.clearErrors(); ec.message.popErrors() }
    rowList.push(Object.assign(row, {kindLabel: row.repositoryKind === 'db' ? L('Database') : row.repositoryKind === 'remote' ? L('Mirror') : L('Disk'),
        branch: row.branch || 'main', projectsText: row.projectList.map((project) => project.workEffortName).join(', '),
        lastText: row.lastUpdateDate ? ec.l10n.format(row.lastUpdateDate, 'MMM d, yyyy') : '',
        openMergeRequestCount: row.openMergeRequestCount || 0, httpsUrl: urls.httpsUrl || '', sshUrl: isClient ? '' : (urls.sshUrl || '')}))
}

effortMap = {}
const ids = Array.from(new Set(Array.from(workEffortIdList || []).filter((id) => id)))
if (!ids.length) return
ec.message.pushErrors()
try {
    const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    const visible = new Set(Array.from(vis.visibleProjectIds || []))
    const managed = new Set(Array.from(vis.managedProjectIds || []))
    const restricted = new Set(Array.from(vis.restrictedItemIds || []))
    const shared = vis.itemVisibilityIds == null ? null : Array.from(vis.itemVisibilityIds)
    const all = !!vis.allProjects && !vis.isClient
    // never a confidential issue's task the user is no Owner of, a project's manager included (HiddenItems.js): a
    // commit or a merge request that names one shows no link to it
    const rows = Array.from(ec.resource.script('component://mr-boss/service/ironstone/projects/HiddenItems.js').without(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', ids), vis)
            .selectField('workEffortId,workEffortName,statusId,workEffortTypeEnumId,rootWorkEffortId,visibilityEnumId').disableAuthz().list())
    for (const row of rows) {
        const isProject = row.workEffortTypeEnumId === 'WetProject'
        const projectId = isProject ? row.workEffortId : row.rootWorkEffortId
        if (!all && (!projectId || !visible.has(projectId))) continue
        if (row.workEffortTypeEnumId === 'WetTask') {
            if (shared != null) { if (!shared.includes(row.visibilityEnumId)) continue }
            else if (!all && ['WevRestricted', 'WevConfidential'].includes(row.visibilityEnumId) && !managed.has(projectId) && !restricted.has(row.workEffortId)) continue
        } else if (!isProject && shared != null && !['WetMilestone', 'WetRelease'].includes(row.workEffortTypeEnumId)) continue
        effortMap[row.workEffortId] = {workEffortId: row.workEffortId, workEffortName: row.workEffortName || '', statusId: row.statusId,
            workEffortTypeEnumId: row.workEffortTypeEnumId, rootWorkEffortId: row.rootWorkEffortId}
    }
} catch (err) {
    ec.logger.error(`Work efforts of code links not checked, none shown: ${err && err.message ? err.message : err}`)
    effortMap = {}
} finally { ec.message.clearErrors(); ec.message.popErrors() }

const content = contentRepository === 'Y' || contentRepository === true
const isAdmin = ec.user.isInGroup('ADMIN')
if (workEffortId) {
    ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId, need: 'manage'}).call()
    if (ec.message.hasError()) return
    const out = ec.service.sync().name('mantle.work.GitServices.create#ProjectRepository').parameters({workEffortId, repositoryId: repositoryId || null,
        description: description || null, repositoryKind: repositoryKind || null, contentRepository: content}).disableAuthz().call()
    if (ec.message.hasError()) return
    repositoryId = out.repositoryId
} else {
    if (!isAdmin) { ec.message.addError(ec.l10n.localize('Choose the project the repository is for')); return }
    if (!repositoryId || !/^[A-Za-z0-9][A-Za-z0-9_.-]*$/.test(repositoryId) || repositoryId.endsWith('.git')) {
        ec.message.addError(ec.l10n.localize("A repository ID has letters, digits, '_', '.' and '-', and does not end in .git")); return }
    if (ec.entity.find('moqui.resource.GitRepository').condition('repositoryId', repositoryId).one() != null) {
        ec.message.addError(ec.resource.expand('Git repository ${repositoryId} already exists', '', {repositoryId})); return }
    const kind = ['local', 'db'].includes(repositoryKind) ? repositoryKind : 'local'
    ec.service.sync().name('create#moqui.resource.GitRepository').parameters({repositoryId, repositoryKind: kind, branch: 'main', description: description || null}).call()
    ec.service.sync().name('org.moqui.git.GitServices.init#GitRepository').parameters({repositoryId, contentRepository: content}).call()
    if (ec.message.hasError()) return
}
if (importUrl) {
    const kind = ec.entity.find('moqui.resource.GitRepository').condition('repositoryId', repositoryId).one()?.repositoryKind
    if (kind !== 'db') { ec.message.addError(ec.l10n.localize('Only a repository in the database imports from a URL')); return }
    ec.service.sync().name('org.moqui.git.GitServices.import#GitRepository').parameters({repositoryId, source: String(importUrl).trim()}).disableAuthz().call()
    if (ec.message.hasError()) return
}
message = ec.resource.expand('Repository ${repositoryId} made', '', {repositoryId})

ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId, need: 'manage'}).call()
if (ec.message.hasError()) return
const access = ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess').parameters({repositoryId}).call() || {}
if (!access.canView) { ec.message.addError(ec.resource.expand('Repository ${repositoryId} is not available', '', {repositoryId})); return }
if (!access.canDelete) { ec.message.addError(ec.resource.expand('Only the maintainers of ${repositoryId} link it to a project', '', {repositoryId})); return }
ec.service.sync().name('mantle.work.GitServices.add#ProjectRepository').parameters({workEffortId, repositoryId}).disableAuthz().call()
if (!ec.message.hasError()) message = ec.resource.expand('${repositoryId} linked to ${workEffortId}', '', {repositoryId, workEffortId})

if (!ec.user.isInGroup('ADMIN')) { ec.message.addError(ec.l10n.localize('Only administrators make mirrors')); return }
if (!/^[A-Za-z0-9][A-Za-z0-9_.-]*$/.test(repositoryId) || repositoryId.endsWith('.git')) {
    ec.message.addError(ec.l10n.localize("A repository ID has letters, digits, '_', '.' and '-', and does not end in .git")); return }
if (ec.entity.find('moqui.resource.GitRepository').condition('repositoryId', repositoryId).one() != null) {
    ec.message.addError(ec.resource.expand('Git repository ${repositoryId} already exists', '', {repositoryId})); return }
if (!/^(https?|ssh|file):\/\//.test(String(remoteUrl).trim())) { ec.message.addError(ec.l10n.localize('A mirror URL is https, ssh or file')); return }
ec.service.sync().name('create#moqui.resource.GitRepository').parameters({repositoryId, repositoryKind: 'remote', remoteUrl: String(remoteUrl).trim(),
    description: description || null, username: username || null, accessToken: accessToken || null,
    fetchIntervalMinutes: fetchIntervalMinutes ?? null}).call()
if (ec.message.hasError()) return
if (workEffortId) ec.service.sync().name('mantle.work.GitServices.add#ProjectRepository').parameters({workEffortId, repositoryId}).call()
// the first fetch: one that fails is recorded on the row (lastFetchError) and the mirror stays
ec.message.pushErrors()
try { ec.service.sync().name('org.moqui.git.GitServices.init#GitRepository').parameters({repositoryId}).call() }
catch (err) { ec.logger.warn(`Mirror ${repositoryId}: the first fetch failed: ${err}`) }
finally {
    if (ec.message.hasError()) ec.logger.warn(`Mirror ${repositoryId}: the first fetch failed: ${ec.message.getErrorsString()}`)
    ec.message.clearErrors(); ec.message.popErrors()
}
message = ec.resource.expand('Mirror ${repositoryId} made', '', {repositoryId})

optionList = []
const refs = ec.service.sync().name('org.moqui.git.GitServices.get#GitRefs').parameters({repositoryId}).call() || {}
defaultBranch = refs.defaultBranch || 'main'
const list = Array.from(refs.refList || [])
const branches = list.filter((ref) => ref.refType === 'branch').sort((a, b) => (b.isDefault ? 1 : 0) - (a.isDefault ? 1 : 0) || String(a.shortName).localeCompare(String(b.shortName)))
const tags = list.filter((ref) => ref.refType === 'tag').sort((a, b) => Number(b.commitDate || 0) - Number(a.commitDate || 0))
for (const ref of branches) optionList.push({key: ref.shortName, text: ref.shortName + (ref.isDefault ? ' (' + ec.l10n.localize('default') + ')' : '')})
for (const ref of tags) optionList.push({key: ref.shortName, text: ec.l10n.localize('Tag') + ' ' + ref.shortName})

found = false; isFile = false; entryList = []; file = null; readme = null; crumbList = []
const clean = String(path || '').split('/').filter((part) => part && part !== '.' && part !== '..').join('/')
const tree = ec.service.sync().name('org.moqui.git.GitServices.get#GitTree').parameters({repositoryId, revision: ref || null, path: clean || null}).call() || {}
if (ec.message.hasError() || !tree.commitId) return
found = true
commitId = tree.commitId
if (!ref) ref = tree.branch || null
const parts = clean ? clean.split('/') : []
crumbList = parts.map((name, index) => ({name, path: parts.slice(0, index + 1).join('/'), last: index === parts.length - 1}))
const fmt = (value) => value ? ec.l10n.format(value, 'MMM d, yyyy') : ''
const size = (bytes) => bytes == null ? '' : bytes < 1024 ? bytes + ' B' : bytes < 1048576 ? (Math.round(bytes / 102.4) / 10) + ' KB' : (Math.round(bytes / 104857.6) / 10) + ' MB'
if (tree.isFile) {
    isFile = true
    const name = parts[parts.length - 1] || clean
    const blob = ec.service.sync().name('org.moqui.git.GitServices.get#GitBlob').parameters({repositoryId, revision: commitId, path: clean}).call() || {}
    const image = /\.(png|jpe?g|gif|webp|svg|ico|bmp)$/i.test(name)
    const log = ec.service.sync().name('org.moqui.git.GitServices.get#GitLog').parameters({repositoryId, revision: commitId, path: clean, limit: 1}).call() || {}
    const last = Array.from(log.commitList || [])[0] || null
    const tooLarge = (blob.size || 0) > 1048576
    file = {path: clean, name, size: blob.size || 0, sizeText: size(blob.size || 0), isImage: image, isText: blob.text != null && !image && !tooLarge,
        text: blob.text != null && !image && !tooLarge ? blob.text : null, isMarkdown: /\.(md|markdown)$/i.test(name), tooLarge,
        lastCommit: last ? {commitId: last.commitId, shortId: last.shortId, summary: last.summary, authorName: last.authorName, dateText: fmt(last.committerDate)} : null}
    return
}
for (const entry of Array.from(tree.entryList || [])) {
    const last = entry.lastCommit || null
    entryList.push({name: entry.name, path: entry.path, type: entry.type, isDir: entry.type === 'dir', lfs: !!entry.lfs,
        icon: entry.type === 'dir' ? 'sym_o_folder' : entry.type === 'submodule' ? 'sym_o_folder_special' : entry.type === 'link' ? 'sym_o_link' : 'sym_o_draft',
        sizeText: entry.type === 'dir' ? '' : size(entry.size), commitId: last?.commitId || null, shortId: last?.shortId || '',
        summary: last?.summary || '', authorName: last?.authorName || '', dateText: fmt(last?.committerDate)})
}
const readmeEntry = entryList.find((entry) => !entry.isDir && /^readme\.(md|markdown)$/i.test(entry.name)) || entryList.find((entry) => !entry.isDir && /^readme(\.txt)?$/i.test(entry.name))
if (readmeEntry) {
    const blob = ec.service.sync().name('org.moqui.git.GitServices.get#GitBlob').parameters({repositoryId, revision: commitId, path: readmeEntry.path}).call() || {}
    if (blob.text != null && (blob.size || 0) <= 524288) readme = {name: readmeEntry.name, text: blob.text, isMarkdown: /\.(md|markdown)$/i.test(readmeEntry.name)}
}

commitList = []; hasMore = false
const log = ec.service.sync().name('org.moqui.git.GitServices.get#GitLog').parameters({repositoryId, revision: ref || null, path: path || null,
    afterCommitId: afterCommitId || null, limit: limit}).call() || {}
if (ec.message.hasError()) return
hasMore = !!log.hasMore
const commits = Array.from(log.commitList || [])
if (!commits.length) return
const ids = commits.map((commit) => commit.commitId)
const items = ec.service.sync().name('ironstone.projects.CodeServices.get#CommitItems').parameters({repositoryId, commitIdList: ids}).call()?.itemsByCommit || {}
let states = {}
ec.message.pushErrors()
try { states = ec.service.sync().name('org.moqui.git.GitServices.get#GitCommitStatuses').parameters({repositoryId, commitIdList: ids}).call()?.stateByCommit || {} }
catch (err) { ec.logger.warn(`Commits of ${repositoryId}: the checks were not read: ${err}`) }
finally { ec.message.clearErrors(); ec.message.popErrors() }
for (const commit of commits) commitList.push({commitId: commit.commitId, shortId: commit.shortId, summary: commit.summary,
    authorName: commit.authorName, authorEmail: commit.authorEmail, moquiUserId: commit.moquiUserId || null,
    dateText: commit.committerDate ? ec.l10n.format(commit.committerDate, 'MMM d, yyyy h:mm a') : '',
    itemList: items[commit.commitId] || [], checkState: states[commit.commitId] || null})

itemsByCommit = {}
const ids = Array.from(commitIdList || [])
if (!ids.length) return
// only of a repository the user may view (the screens checked it; a service checks again)
ec.message.pushErrors()
let canView = false
try { canView = !!ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess').parameters({repositoryId}).call()?.canView && !ec.message.hasError() }
catch (err) { canView = false }
finally { ec.message.clearErrors(); ec.message.popErrors() }
if (!canView) return
const links = Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitCommit').condition('repositoryId', repositoryId).condition('commitId', 'in', ids).disableAuthz().list())
if (!links.length) return
const efforts = ec.service.sync().name('ironstone.projects.CodeServices.get#VisibleWorkEfforts').parameters({workEffortIdList: links.map((link) => link.workEffortId)})
        .call()?.effortMap || {}
for (const link of links) {
    const effort = efforts[link.workEffortId]
    if (!effort) continue
    ;(itemsByCommit[link.commitId] = itemsByCommit[link.commitId] || []).push({workEffortId: link.workEffortId, workEffortName: effort.workEffortName || '',
        statusId: effort.statusId, linkSourceEnumId: link.linkSourceEnumId})
}

branchList = []
const refs = ec.service.sync().name('org.moqui.git.GitServices.get#GitRefs').parameters({repositoryId, refType: 'branch'}).call() || {}
if (ec.message.hasError()) return
defaultBranch = refs.defaultBranch || 'main'
const branches = Array.from(refs.refList || []).sort((a, b) => (b.isDefault ? 1 : 0) - (a.isDefault ? 1 : 0) || Number(b.commitDate || 0) - Number(a.commitDate || 0))
const links = Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitRef').condition('repositoryId', repositoryId).condition('refType', 'branch')
        .condition('thruDate', 'is-null', null).disableAuthz().list())
// a branch's work item only when the user sees it (a client: one shared with it)
const seen = links.length ? ec.service.sync().name('ironstone.projects.CodeServices.get#VisibleWorkEfforts').parameters({workEffortIdList: links.map((link) => link.workEffortId)})
        .call()?.effortMap || {} : {}
let open = []
ec.message.pushErrors()
try { open = Array.from(ec.service.sync().name('org.moqui.git.GitReviewServices.find#MergeRequests').parameters({repositoryId,
    statusIdList: ['GmrDraft', 'GmrOpen'], pageSize: 200}).call()?.mergeRequestList || []) }
catch (err) { ec.logger.warn(`Branches of ${repositoryId}: the merge requests were not read: ${err}`) }
finally { ec.message.clearErrors(); ec.message.popErrors() }
let states = {}
ec.message.pushErrors()
try { states = ec.service.sync().name('org.moqui.git.GitServices.get#GitCommitStatuses').parameters({repositoryId,
    commitIdList: branches.map((ref) => ref.commitId).filter((id) => id)}).call()?.stateByCommit || {} }
catch (err) { ec.logger.warn(`Branches of ${repositoryId}: the checks were not read: ${err}`) }
finally { ec.message.clearErrors(); ec.message.popErrors() }
let compared = 0
for (const ref of branches) {
    const row = {name: ref.shortName, refName: ref.refName, commitId: ref.commitId, shortId: ref.commitId ? String(ref.commitId).substring(0, 10) : '',
        summary: ref.summary || '', authorName: ref.authorName || '', dateText: ref.commitDate ? ec.l10n.format(ref.commitDate, 'MMM d, yyyy') : '',
        isDefault: !!ref.isDefault, aheadBy: null, behindBy: null, checkState: states[ref.commitId] || null, mergeRequest: null, item: null}
    const link = links.find((one) => one.refName === ref.refName && seen[one.workEffortId])
    if (link) row.item = {workEffortId: link.workEffortId, workEffortName: seen[link.workEffortId].workEffortName || ''}
    const mr = open.find((one) => one.sourceRef === ref.shortName)
    if (mr) row.mergeRequest = {mergeRequestId: mr.mergeRequestId, mergeRequestNum: mr.mergeRequestNum, title: mr.title}
    if (!row.isDefault && compared < 20) {
        compared++
        ec.message.pushErrors()
        try {
            const cmp = ec.service.sync().name('org.moqui.git.GitServices.get#GitCompare').parameters({repositoryId, base: 'refs/heads/' + defaultBranch,
                head: ref.refName}).call() || {}
            if (!ec.message.hasError()) { row.aheadBy = cmp.aheadBy ?? null; row.behindBy = cmp.behindBy ?? null }
        } catch (err) { ec.logger.warn(`Branch ${ref.shortName} of ${repositoryId}: not compared: ${err}`) }
        finally { ec.message.clearErrors(); ec.message.popErrors() }
    }
    row.aheadText = row.aheadBy == null ? '' : row.aheadBy + ' ↑ · ' + row.behindBy + ' ↓'
    branchList.push(row)
}

tagList = []
const refs = ec.service.sync().name('org.moqui.git.GitServices.get#GitRefs').parameters({repositoryId, refType: 'tag'}).call() || {}
if (ec.message.hasError()) return
const tags = Array.from(refs.refList || []).sort((a, b) => Number(b.tag?.taggerDate || b.commitDate || 0) - Number(a.tag?.taggerDate || a.commitDate || 0))
const links = Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitRef').condition('repositoryId', repositoryId).condition('refType', 'tag')
        .condition('thruDate', 'is-null', null).disableAuthz().list())
// the linked work efforts the user sees (a client: its projects, their milestones and releases, the items shared with it)
const efforts = links.length ? ec.service.sync().name('ironstone.projects.CodeServices.get#VisibleWorkEfforts').parameters({workEffortIdList: links.map((link) => link.workEffortId)})
        .call()?.effortMap || {} : {}
const typeLabel = {WetProject: 'Project', WetMilestone: 'Milestone', WetRelease: 'Release', WetTask: 'Work item', WetSprint: 'Sprint'}
