part('the branches', () => {
    const links = Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitRef').condition('workEffortId', workEffortId).condition('refType', 'branch')
            .condition('thruDate', 'is-null', null).orderBy('-linkedDate').disableAuthz().list())
