        const row = {repositoryId: link.repositoryId, refName: link.refName, name, exists: !!ref, commitId: ref?.commitId || link.objectId || null,
            shortId: (ref?.commitId || link.objectId) ? String(ref?.commitId || link.objectId).substring(0, 10) : '', summary: ref?.summary || '',
            dateText: ref?.commitDate ? fmt(ref.commitDate) : '', aheadBy: null, behindBy: null, aheadText: '', checkLabel: '', checkColor: '',
