                if (!ec.message.hasError()) { row.aheadBy = cmp.aheadBy ?? null; row.behindBy = cmp.behindBy ?? null }
            } catch (err) { ec.logger.warn(`Development of ${workEffortId}: ${name} not compared: ${err}`) }
            finally { ec.message.clearErrors(); ec.message.popErrors() }
            row.aheadText = row.aheadBy == null ? '' : row.aheadBy + ' ↑ · ' + row.behindBy + ' ↓'
        }
        if (row.commitId) (heads[link.repositoryId] = heads[link.repositoryId] || []).push(row.commitId)
        const mr = development.mergeRequestList.find((one) => one.repositoryId === link.repositoryId && one.sourceRef === name && ['GmrDraft', 'GmrOpen'].includes(one.statusId))
        if (mr) row.mergeRequest = {mergeRequestId: mr.mergeRequestId, numText: mr.numText, url: mr.url}
        development.branchList.push(row)
    }
    for (const repositoryId of Object.keys(heads)) {
        const states = ec.service.sync().name('org.moqui.git.GitServices.get#GitCommitStatuses').parameters({repositoryId, commitIdList: heads[repositoryId]})
                .call()?.stateByCommit || {}
        for (const row of development.branchList.filter((one) => one.repositoryId === repositoryId)) {
            const check = states[row.commitId] ? labels.check[states[row.commitId]] || null : null
            if (check) { row.checkLabel = check[0]; row.checkColor = check[1] }
        }
    }
    // a branch ahead of the default with no open merge request may open one (Compare)
    for (const row of development.branchList) row.canOpenMergeRequest = row.exists && !row.mergeRequest && Number(row.aheadBy || 0) > 0
            && development.repositoryList.some((repo) => repo.repositoryId === row.repositoryId && repo.canPush)
})
part('the commits', () => {
    const links = Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitCommit').condition('workEffortId', workEffortId).orderBy('-commitDate')
            .limit(60).disableAuthz().list())
    const labelsBy = {WglsExplicit: L('By hand'), WglsMessage: L('Commit message'), WglsTrailer: L('Task trailer')}
    for (const link of links) {
        if (!accessOf(link.repositoryId)) continue
        if (development.commitList.length >= 30) break
        development.commitList.push({repositoryId: link.repositoryId, commitId: link.commitId, shortId: String(link.commitId).substring(0, 10),
            summary: link.summary || '', authorName: link.authorName || '', dateText: fmt(link.commitDate),
            refText: link.refName ? String(link.refName).replace(/^refs\/(heads|tags)\//, '') : '', linkedBy: labelsBy[link.linkSourceEnumId] || L('Linked')})
    }
})
part('the tags', () => {
    const links = Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitRef').condition('workEffortId', workEffortId).condition('refType', 'tag')
            .condition('thruDate', 'is-null', null).orderBy('-linkedDate').disableAuthz().list())
    for (const link of links) {
        if (!accessOf(link.repositoryId)) continue
        development.tagList.push({repositoryId: link.repositoryId, name: String(link.refName).replace(/^refs\/tags\//, ''), commitId: link.objectId || null,
            shortId: link.objectId ? String(link.objectId).substring(0, 10) : '', whenText: fmt(link.linkedDate)})
    }
})
part('the branch name', () => {
    development.branchName = ec.service.sync().name('mantle.work.GitServices.get#TaskBranchName').parameters({workEffortId}).call()?.branchName || ''
})
development.canCreateBranch = !!access.canUpdate && development.repositoryList.some((repo) => repo.canPush)
development.pushRepositoryOptions = development.repositoryList.filter((repo) => repo.canPush).map((repo) => ({key: repo.repositoryId,
    text: repo.repositoryId + ' (' + L('from') + ' ' + repo.defaultBranch + ')'}))

ec.service.sync().name('ironstone.commons.TaskServices.get#TaskAccess').parameters({workEffortId, need: 'update', app: 'projects'}).call()
if (ec.message.hasError()) return
const task = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (repositoryId && task?.rootWorkEffortId && !ec.entity.find('mantle.work.effort.WorkEffortGitRepository').condition({workEffortId: task.rootWorkEffortId, repositoryId})
        .conditionDate('fromDate', 'thruDate', null).count()) {
    ec.message.addError(ec.resource.expand('Repository ${repositoryId} is not one of the project\'s', '', {repositoryId})); return }
const out = ec.service.sync().name('mantle.work.GitServices.create#TaskBranch').parameters({workEffortId, repositoryId: repositoryId || null,
    fromRef: fromRef || null, branchName: branchName && String(branchName).trim() ? String(branchName).trim() : null}).call() || {}
if (ec.message.hasError()) return
branchName = out.branchName
repositoryId = out.repositoryId
message = ec.resource.expand('Branch ${branchName} made in ${repositoryId}: git fetch origin, then git checkout ${branchName}', '', {branchName, repositoryId})
